css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; overflow: hidden; border-radius: 10px; }
.loader .head { position: absolute; left: 28%; top: 18%; width: 44%; height: 60%; border-radius: 46% 46% 42% 42% / 52% 52% 60% 60%; box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 70%, transparent); }
.loader .mesh { position: absolute; left: 26%; top: 16%; width: 48%; height: 64%; background: repeating-linear-gradient(90deg, color-mix(in srgb, var(--accent) 32%, transparent) 0 1px, transparent 1px 12%), repeating-linear-gradient(color-mix(in srgb, var(--accent) 32%, transparent) 0 1px, transparent 1px 12%); animation: face-mesh calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
.loader .beam { position: absolute; left: 20%; right: 20%; top: 0; height: 6%; border-radius: 3px; background: linear-gradient(90deg, transparent, var(--accent-2), transparent); box-shadow: 0 0 12px var(--accent-2); animation: face-beam calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
.loader span { position: absolute; width: 16%; height: 16%; border: 2px solid var(--accent-2); }
.loader span:nth-of-type(1) { left: 6%; top: 6%; border-right: 0; border-bottom: 0; }
.loader span:nth-of-type(2) { right: 6%; top: 6%; border-left: 0; border-bottom: 0; }
.loader span:nth-of-type(3) { left: 6%; bottom: 6%; border-right: 0; border-top: 0; }
.loader span:nth-of-type(4) { right: 6%; bottom: 6%; border-left: 0; border-top: 0; }
@keyframes face-beam { 0%, 100% { top: 8%; } 50% { top: 86%; } }
@keyframes face-mesh { 0%, 100% { opacity: .35; } 50% { opacity: 1; } }
